function init(k:K){if(k==='vendor')return{vendor_code:'',vendor_name:'',credit_days:'--- Select ---',tax_zone:'--- Select ---',currency_code:'--- Select ---',vendor_type:'--- Select ---',status:'',return_flag:true,country:'INDIA',billing_country:'INDIA',bypass_sku_vendor_link:'No',return_acceptance_days:'30',return_location_type:'--- Select ---',location_type_priority:false,location_type:'--- Select ---',allow_hopping:true,vendor_business_entity:'--- Select ---',otp_verification:'--- Select ---',default_receipt_po:'--- Select ---',default_receipt_asn:'--- Select ---',default_receipt_di:'--- Select ---',default_delivery_mode:'--- Select ---',marketplace_invoice_number:'--- Select ---',documents:[]};if(k==='transporter')return{carrier_type:'--- Select ---',transporter_type:'Courier',transporter_code:'',transporter_name:'',delivery_mode:'--- Select ---',country:'INDIA',state:'---Select State ---',is_active:false};return{customer_code:'',customer_name:'',is_active:true,type:'--- Select ---',payment_terms:'--- Select ---',tax_zone:'--- Select ---',tcs_percentage:'--- Select ---',shipping_country:'INDIA',billing_country:'INDIA',geo_type:'--- Select ---',invoice_report:'--- Select ---',shelf_life_picking_type:'--- Select ---',picking_instructions:[],shipping_instructions:[],other_shipping_addresses:[]}}
