function Enquiry({kind,cols,rows,loading,searched,filters,setFilters,search,reset,download,importAction,add,edit}:any){const total=rows.length;return <div><div className="mb-2 flex justify-end gap-2">{(kind==='transporter'?[['Search',search,'bg-[#ef9d18] text-white'],['Reset',reset,'border bg-white'],['Download',download,'border bg-white'],['Add New',add,'border bg-white']]:[['Search',search,'bg-[#ef9d18] text-white'],['Reset',reset,'border bg-white'],['Import',importAction,'border bg-white'],['Export',download,'border bg-white'],['Add New',add,'border bg-white']]).map(([l,fn,cl]:any)=><button key={l} onClick={fn} className={`rounded px-4 py-2 text-sm ${cl}`}>{l}</button>)}<HelpCircle size={19} className="text-[#318abb]"/></div><div className="overflow-x-auto border bg-white"><table className="w-full min-w-[900px] text-sm"><thead><tr className="bg-[#f6f6f6]">{cols.map((x:any,i:number)=><th key={x[0]} className="border-b px-2 pb-1 pt-3 text-center">{x[1]}{i===0?' ↑':''}</th>)}</tr><tr className="bg-[#f6f6f6]">{cols.map((x:any)=><th key={x[0]} className="border-b px-2 pb-2"><div className="flex border bg-white"><GridFilter kind={kind} field={x[0]} value={filters[x[0]]||''} set={(value:string)=>setFilters((current:any)=>({...current,[x[0]]:value}))} search={search}/></div></th>)}</tr></thead><tbody>{loading?<tr><td colSpan={cols.length} className="h-64 text-center"><span className="inline-block h-8 w-8 animate-spin rounded-full border-2 border-slate-200 border-t-[#258eb2]"/><div>Loading…</div></td></tr>:rows.length?rows.slice(0,20).map((r:any,i:number)=><tr key={r.id??i} className="border-b hover:bg-[#eaf5fa]">{cols.map((x:any)=><td key={x[0]} className="px-3 py-2 text-center">{x[0]===`${kind}_code`?<button onClick={()=>edit(r)} className="text-[#2378ad] hover:underline">{r[x[0]]}</button>:x[0]==='is_active'?<Ribbon value={r.is_active?'Active':'Inactive'}/>:x[0]==='status'?<Ribbon value={r.status}/>:r[x[0]]}</td>)}</tr>):<tr><td colSpan={cols.length} className="h-64 text-center text-slate-400">No records to view</td></tr>}</tbody></table><div className="flex items-center justify-between border-t px-3 py-2 text-sm"><div className="flex items-center gap-1"><Pg><ChevronsLeft size={14}/></Pg><Pg><ChevronLeft size={14}/></Pg><span className="px-2">Page <input value={total?1:0} readOnly className="w-10 border text-center"/> of {total?Math.ceil(total/20):0}</span><Pg><ChevronRight size={14}/></Pg><Pg><ChevronsRight size={14}/></Pg><select title="Records per Page" className="ml-2 border px-2 py-1"><option>20</option><option>50</option><option>100</option><option>200</option></select></div><span>{total?`View 1-${Math.min(20,total)} of ${total}`:'No records to view'}</span></div></div></div>}
function GridFilter({kind,field,value,set,search}:any){const options=kind==='vendor'?({vendor_type:['--- Select ---','B2S2','JIT','Marketplace','Outright purchase'],credit_days:['--- Select ---','1','120','120 days from the date of receipt of goods','35 Days','50 Days','7 days','7 Days','75 DAYS','Letter of Credit','30 Days','45 Days','60 Days','90 Days','Advance'],country:countries,state:['--- Select ---'],status:['--- Select ---','Confirmed','Deactivated','Pending Confirmation']} as Record<string,string[]>)[field]:kind==='customer'?({type:['--- Select ---','0 - Last','1 - B2C','2 - B2B'],is_active:['- Select -','InActive','Active']} as Record<string,string[]>)[field]:kind==='transporter'?({transporter_type:['--- Select ---','Courier','Own Fleet'],country:countries,state:['--- Select ---'],status:['--- Select ---','InActive','Active']} as Record<string,string[]>)[field]:undefined;return <>{options?<select aria-label={`${field} filter`} value={value} onChange={e=>set(e.target.value)} className="h-[23px] w-full bg-white px-1 text-xs">{options.map((option,index)=><option key={`${option}-${index}`} value={option==='--- Select ---'||option==='- Select -'?'':option}>{option}</option>)}</select>:<input aria-label={`${field} filter`} value={value} onChange={e=>set(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()} className="w-full px-2 py-1.5 outline-none"/>}<Search size={13} className="m-2 text-slate-400"/></>}
function Pg({children}:{children:any}){return <button className="flex h-7 w-7 items-center justify-center border bg-white">{children}</button>}function Ribbon({value}:{value:string}){const a=value==='Confirmed'||value==='Active',p=value==='Pending Confirmation';return <span className={`inline-block min-w-24 [clip-path:polygon(0_0,92%_0,100%_50%,92%_100%,0_100%,7%_50%)] px-3 py-1 text-xs font-semibold text-white ${a?'bg-[#36a853]':p?'bg-[#d89d27]':'bg-[#999]'}`}>{value}</span>}
function Editor({kind,tabs,tab,setTab,fields,form,update,errors,busy,saved,notice,save,reset,back,confirm,deactivate,parent,link,audit}:any){return <div><div className="mb-3 flex justify-end gap-2">{kind==='vendor'&&<button onClick={reset} className="rounded border bg-white px-4 py-2 text-sm">Add New</button>}<button onClick={save} disabled={busy} className={`rounded px-4 py-2 text-sm text-white ${kind==='vendor'?'bg-[#ef9d18]':'bg-[#2788b8]'}`}>Save</button>{kind==='vendor'?<><button onClick={link} className="rounded border bg-white px-4 py-2 text-sm">Link To Store</button><button onClick={confirm} className="rounded bg-[#39a855] px-4 py-2 text-sm text-white">Confirm</button><button onClick={deactivate} className="rounded bg-[#8a35aa] px-4 py-2 text-sm text-white">Deactivate</button></>:<button onClick={reset} className="rounded border bg-white px-4 py-2 text-sm">Reset</button>}<button onClick={audit} className="rounded bg-[#2b9dbc] px-4 py-2 text-sm text-white">Audit</button><button aria-label="Close vendor editor" onClick={back} className="rounded border bg-white px-3"><X size={15}/></button></div><div className="border bg-white"><div className="flex overflow-x-auto border-b bg-[#f6f6f6]">{tabs.map((t:string)=><button key={t} onClick={()=>setTab(t)} className={`whitespace-nowrap border-r px-5 py-3 text-sm ${tab===t?'border-b-2 border-b-[#278eb8] bg-white font-semibold text-[#278eb8]':''}`}>{t}</button>)}</div><div className="min-h-[430px] p-5">{kind==='vendor'&&tab==='Attached Document'?<Docs form={form} update={update}/>:kind==='vendor'&&tab==='Terms and Conditions'?<Terms form={form} update={update}/>:kind==='customer'&&tab==='Other Shipping Addresses'?<Other form={form} update={update} saved={saved} notice={notice}/>:kind==='transporter'&&tab==='Linked Location'?<LinkedLocations/>:<><div className="grid grid-cols-1 gap-x-6 gap-y-4 md:grid-cols-2 xl:grid-cols-3">{fields.map((x:F)=><Input key={x.key} field={x} form={form} update={update} error={errors[x.key]} parent={parent}/>)}</div>{((kind==='vendor'&&tab==='Vendor Master')||(kind==='transporter'&&tab==='Transporter Details'))&&<h3 className="mt-7 border-b pb-2 font-semibold text-slate-600">{kind==='vendor'?'Bank Details':'Contact Details'}</h3>}</>}</div></div></div>}
function Input({field,form,update,error,parent}:any){const v=form[field.key]??(field.type==='check'?false:field.multiple?[]:'');if(field.type==='check')return <label className="flex items-center gap-2 pt-6 text-sm"><input data-field={field.key} aria-label={field.label} type="checkbox" checked={!!v} disabled={field.disabled} onChange={e=>update(field.key,e.target.checked)} className="h-4 w-4 accent-[#278eb8]"/>{field.label}</label>;return <label className="block text-sm"><span>{field.label}{field.required&&<b className="text-red-500"> *</b>}</span><div className="mt-1 flex">{field.type==='select'?<select data-field={field.key} aria-label={field.label} value={v} multiple={field.multiple} size={field.multiple?5:undefined} disabled={field.disabled} onChange={e=>update(field.key,field.multiple?[...e.target.selectedOptions].map(option=>option.value):e.target.value)} className={`inp ${field.multiple?'h-28':''} ${error?'border-red-500':''}`}>{field.options.map((o:string,i:number)=><option key={`${o}-${i}`}>{o}</option>)}</select>:<input data-field={field.key} aria-label={field.label} type={field.type||'text'} value={v} maxLength={field.maxLength} disabled={field.disabled} readOnly={field.readOnly} onChange={e=>update(field.key,e.target.value)} className={`inp ${field.readOnly?'bg-slate-100':''} ${error?'border-red-500':''}`}/>} {field.type==='picker'&&<button type="button" onClick={parent} className="ml-1 rounded bg-[#299fbd] px-3 text-white">...</button>}</div>{error&&<small className="text-red-500">{error}</small>}</label>}
function Docs({form,update}:any){const d=form.documents||[];return <div><div className="flex items-end gap-2"><label className="text-sm">Document Attached<input type="file" className="mt-1 block border p-1.5" onChange={e=>{const x=e.target.files?.[0];if(x)update('pending_document',x.name)}}/></label><button onClick={()=>form.pending_document&&update('documents',[...d,{name:form.pending_document,id:Date.now()}])} className="rounded bg-[#299fbd] px-3 py-2 text-white">Add New Row</button><button onClick={()=>update('documents',d.slice(0,-1))} className="rounded border px-3 py-2">Delete Row</button></div><table className="mt-5 w-full border"><thead><tr className="bg-slate-100"><th className="p-2">Document Attached</th></tr></thead><tbody>{d.map((x:any)=><tr key={x.id} className="border-t"><td className="p-2">{x.name}</td></tr>)}</tbody></table></div>}
function Terms({form,update}:any){return <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-3"><Input field={n('return_acceptance_days','Return Acceptance Days')} form={form} update={update}/><Input field={s('return_location_type','Return Location Type',['--- Select ---','Own Location','Vendor Location'])} form={form} update={update}/><Input field={c('location_type_priority','Location Type Priority')} form={form} update={update}/></div>}
function Other({form,update,saved,notice}:any){const r=form.other_shipping_addresses||[],blank={address1:'',address2:'',phone:'',email:'',country:'--- Select ---',state:'--- Select ---',latitude:'',longitude:'',city:'',pin_code:'',gst_no:'',status:true},[open,setOpen]=useState(false),[draft,setDraft]=useState<any>(blank);const change=(key:string,value:any)=>setDraft((old:any)=>({...old,[key]:value}));const save=()=>{if(!saved)return notice('Please save Customer to add Other Shipping Address.');if(!draft.address1)return notice('Please Enter Address 1 In "Other Shipping Address Fields" TAB');if(!draft.phone)return notice('Please Enter Phone No In "Other Shipping Address Fields" TAB');if(!draft.email)return notice('Please Enter Email In "Other Shipping Address Fields" TAB');if(!/^[\w.-]+@([\w-]+\.)+[\w-]{2,4}$/.test(draft.email))return notice('Please Enter Email In Correct Format (eg. abc@xyz.com) In "Other Shipping Address Fields" TAB');if(draft.country==='--- Select ---')return notice('Please Select Country In "Other Shipping Address Fields" TAB ');if(draft.state==='--- Select ---')return notice('Please Select State In "Other Shipping Address Fields" TAB ');update('other_shipping_addresses',[...r,{...draft,id:Date.now()}]);setOpen(false);setDraft(blank)};return <div><button onClick={()=>{setDraft(blank);setOpen(true)}} className="mb-3 rounded bg-[#2788b8] px-4 py-2 text-white"><Plus size={14} className="mr-1 inline"/>Add New</button><div className="overflow-x-auto border"><table className="min-w-[1050px] w-full text-sm"><thead className="bg-slate-100"><tr>{['Address 1','Address 2','Phone','Email','Country','State','City','Pincode','GST No.','Actions'].map(h=><th key={h} className="border p-2">{h}</th>)}</tr></thead><tbody>{r.map((x:any)=><tr key={x.id}>{['address1','address2','phone','email','country','state','city','pin_code','gst_no'].map(k=><td key={k} className="border p-2">{x[k]}</td>)}<td className="border p-2"><button onClick={()=>update('other_shipping_addresses',r.filter((y:any)=>y.id!==x.id))} className="text-red-600">Delete</button></td></tr>)}</tbody></table><div className="flex justify-between bg-slate-100 p-2 text-sm"><span>Page {r.length?1:0} of {r.length?1:0} &nbsp; <select title="Records per Page"><option>10</option><option>15</option><option>20</option></select></span><span>{r.length?`View 1-${r.length} of ${r.length}`:'No records to view'}</span></div></div>{open&&<div role="dialog" aria-label="Customer Create/Edit" className="fixed inset-0 z-[95] grid place-items-center bg-black/40 p-4"><div className="w-[980px] max-w-[96vw] bg-white"><div className="flex justify-between bg-[#358fbd] px-4 py-3 text-white"><b>Customer Create/Edit</b><button aria-label="Close" onClick={()=>setOpen(false)}><X size={18}/></button></div><div className="grid grid-cols-3 gap-4 p-5">{[[f('address1','Address 1',1),1000],[f('address2','Address 2'),50],[f('phone','Phone',1),20],[em('email','Email',1),50],[s('country','Country',countries,1),0],[s('state','State',states,1),0],[f('latitude','Latitude'),0],[f('longitude','Longitude'),0],[f('city','City'),20],[f('pin_code','Pincode'),20],[f('gst_no','GST No.'),25],[c('status','Status'),0]].map(([field,max]:any)=><Input key={field.key} field={{...field,maxLength:max||undefined}} form={draft} update={change}/>)}</div><div className="flex justify-end gap-2 border-t p-3"><button onClick={save} className="rounded bg-[#ef9d18] px-4 py-2 text-white">Save</button><button onClick={()=>setDraft(blank)} className="rounded border px-4 py-2">Delete</button><button onClick={()=>setOpen(false)} className="rounded border px-4 py-2">Close</button></div></div></div>}</div>}
function LinkedLocations(){return <div><div className="mb-4 flex items-end gap-3"><a download="Trans_Location.xlsx" href="data:text/plain," className="text-[#2378ad] underline">Download Template Trans_Location.xlsx</a><input aria-label="Upload Template" type="file" className="border p-1"/><button className="rounded bg-[#2788b8] px-4 py-2 text-white">Import</button><button className="rounded border px-4 py-2">Reset</button></div><div className="overflow-x-auto border"><table className="w-full text-sm"><thead className="bg-slate-100"><tr>{['Location Code','Location Name','Location Type'].map(label=><th key={label} className="border p-2">{label}</th>)}</tr></thead><tbody><tr><td colSpan={3} className="h-60 text-center text-slate-400">No records to view</td></tr></tbody></table><div className="flex justify-between border-t p-2 text-sm"><span>Page 0 of 0 &nbsp; <select title="Records per Page"><option>15</option><option>25</option><option>50</option><option>200</option></select></span><span>No records to view</span></div></div></div>}
function Picker({rows,kind,close,choose}:any){const[q,setQ]=useState(''),[name,setName]=useState(''),[selected,setSelected]=useState<any>(null);const list=rows.filter((r:any)=>String(r[`${kind}_code`]||'').toLowerCase().includes(q.toLowerCase())&&String(r[`${kind}_name`]||'').toLowerCase().includes(name.toLowerCase()));if(kind==='customer')return <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/40"><div className="w-[760px] max-w-[94vw] bg-white"><div className="flex justify-between bg-[#358fbd] p-3 text-white"><b>Select Parent Customer</b><button aria-label="Close parent customer" onClick={close}><X size={18}/></button></div><div className="p-4"><div className="max-h-80 overflow-auto border"><table className="w-full text-sm"><thead className="bg-slate-100"><tr><th className="border p-2">Customer Code</th><th className="border p-2">Customer Name</th><th className="border p-2">Customer Address1</th></tr><tr><th className="border p-1"><input aria-label="Parent Customer Code filter" value={q} onChange={e=>setQ(e.target.value)} className="h-6 w-full border px-1"/></th><th className="border p-1"><input aria-label="Parent Customer Name filter" value={name} onChange={e=>setName(e.target.value)} className="h-6 w-full border px-1"/></th><th className="border p-1"/></tr></thead><tbody>{list.map((r:any)=><tr key={r.id} onClick={()=>setSelected(r)} className={`cursor-pointer border-t text-center hover:bg-[#eaf5fa] ${selected?.id===r.id?'bg-[#d9edf7]':''}`}><td className="p-2">{r.customer_code}</td><td>{r.customer_name}</td><td>{r.billing_address1||''}</td></tr>)}</tbody></table></div><div className="mt-3 flex items-center justify-between"><span>Page {list.length?1:0} of {list.length?1:0} &nbsp; <select title="Records per Page"><option>50</option><option>100</option></select></span><div><button id="selectVendor" onClick={()=>selected&&choose(selected)} className="mr-2 rounded bg-[#2788b8] px-4 py-2 text-white">OK</button><button id="restVendor" onClick={close} className="rounded border px-4 py-2">Close</button></div></div></div></div></div>;return <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/40"><div className="w-[760px] max-w-[94vw] bg-white"><div className="flex justify-between bg-[#358fbd] p-3 text-white"><b>Select Parent Vendor</b><button onClick={close}><X size={18}/></button></div><div className="p-4"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search code or name" className="inp mb-3"/><div className="max-h-80 overflow-auto border"><table className="w-full text-sm"><thead className="bg-slate-100"><tr><th className="p-2">Code</th><th>Name</th><th>Address</th></tr></thead><tbody>{list.map((r:any)=><tr key={r.id} className="border-t text-center hover:bg-[#eaf5fa]"><td className="p-2"><button onClick={()=>choose(r)} className="text-[#2378ad]">{r.vendor_code}</button></td><td>{r.vendor_name}</td><td>{r.shipping_address1||r.status||''}</td></tr>)}</tbody></table></div><div className="mt-3 flex justify-between"><span>Page 1 of 1 &nbsp; 50</span><div><button onClick={close} className="mr-2 rounded bg-[#2788b8] px-4 py-2 text-white">Ok</button><button onClick={close} className="rounded border px-4 py-2">Close</button></div></div></div></div></div>}
function LinkToStore({value,close,save}:{value:string[];close:()=>void;save:(stores:string[])=>void}){
  const[chosen,setChosen]=useState<string[]>(value),{locations,loading,error}=useActiveLocations();
  const stores=locations.map(location=>location.location_name),unconfigured=chosen.filter(store=>!stores.includes(store));
  return <div role="dialog" aria-label="Link To Store" className="fixed inset-0 z-[90] grid place-items-center bg-black/40 p-4"><div className="w-[620px] max-w-full bg-white shadow-2xl"><div className="flex justify-between bg-[#358fbd] px-4 py-3 text-white"><b>Link To Store</b><button onClick={close}><X size={18}/></button></div><div className="p-5">{loading?<p role="status" className="text-sm text-slate-500">Loading active locations…</p>:error?<p role="alert" className="text-sm text-rose-600">{error}</p>:<>{locations.map(location=><label key={location.location_code} className="mb-2 flex gap-2 border p-3"><input type="checkbox" checked={chosen.includes(location.location_name)} onChange={event=>setChosen(current=>event.target.checked?[...current,location.location_name]:current.filter(store=>store!==location.location_name))}/>{location.location_name} ({location.location_code})</label>)}{unconfigured.map(store=><label key={store} className="mb-2 flex gap-2 border border-amber-300 bg-amber-50 p-3 text-amber-900"><input type="checkbox" checked onChange={()=>setChosen(current=>current.filter(value=>value!==store))}/>{store} — previously linked; location is not currently active</label>)}{!locations.length&&!unconfigured.length&&<p className="text-sm text-slate-500">No active locations configured. Add one in Location Create/Edit before linking this vendor.</p>}</>}<div className="mt-4 text-right"><button onClick={close} className="mr-2 rounded border px-4 py-2">Cancel</button><button disabled={loading||!!error} onClick={()=>save(chosen)} className="rounded bg-[#ef9d18] px-4 py-2 text-white disabled:opacity-50">Save</button></div></div></div></div>
}
function VendorAudit({form,close}:{form:any;close:()=>void}){const rows=Array.isArray(form.audit)?form.audit:[];return <div role="dialog" aria-label="Vendor Audit" className="fixed inset-0 z-[90] grid place-items-center bg-black/40 p-4"><div className="w-[640px] max-w-full bg-white shadow-2xl"><div className="flex justify-between bg-[#358fbd] px-4 py-3 text-white"><b>Vendor Audit</b><button aria-label="Close audit" onClick={close}><X size={18}/></button></div><div className="p-5 text-sm">{rows.length?<table className="w-full border-collapse"><thead className="bg-slate-100 text-left"><tr><th className="p-2">Timestamp</th><th className="p-2">Action</th><th className="p-2">User</th></tr></thead><tbody>{rows.map((row:any,index:number)=><tr key={`${row.at}-${index}`} className="border-t"><td className="p-2">{new Date(row.at).toLocaleString()}</td><td className="p-2">{row.action}</td><td className="p-2">{row.by}</td></tr>)}</tbody></table>:<p className="text-slate-400">No audit records to view</p>}<div className="mt-4 text-right"><button onClick={close} className="rounded border px-4 py-2">Close</button></div></div></div></div>}
function CustomerAudit({form,close}:{form:any;close:()=>void}){return <div role="dialog" aria-label="Audit" className="fixed inset-0 z-[90] grid place-items-center bg-black/40 p-4"><div className="w-[640px] max-w-full bg-white shadow-2xl"><div className="flex justify-between bg-[#358fbd] px-4 py-3 text-white"><b>Audit</b><button aria-label="Close audit" onClick={close}><X size={18}/></button></div><div className="grid grid-cols-2 gap-4 p-5 text-sm">{[['Created By',form.created_by],['Created Date',form.created_date],['Modified By',form.modified_by],['Modified Date',form.modified_date]].map(([label,value])=><label key={label}>{label}<input value={value||''} readOnly className="inp mt-1 bg-slate-100"/></label>)}</div></div></div>}
function DiscardDialog({close,discard}:{close:()=>void;discard:()=>void}){return <div role="dialog" aria-label="Discard vendor changes" className="fixed inset-0 z-[100] grid place-items-center bg-black/40 p-4"><div className="w-[420px] bg-white p-5 shadow-2xl"><b>Discard unsaved changes?</b><p className="mt-2 text-sm">Your changes will be lost.</p><div className="mt-4 text-right"><button onClick={close} className="mr-2 rounded border px-4 py-2">Continue editing</button><button onClick={discard} className="rounded bg-[#8a35aa] px-4 py-2 text-white">Discard changes</button></div></div></div>}
